from __future__ import annotations

from typing import Any

from audit_store import AuditStore
from operation_service import OperationService


class ApiHandler:
    def __init__(self) -> None:
        self.audit = AuditStore()
        self.service = OperationService(self.audit)

    def seed(self, resources: list[dict[str, Any]]) -> None:
        self.service.seed(resources)

    def handle(self, payload: dict[str, Any]) -> dict[str, Any]:
        result = self.service.perform(payload)
        if result.get("ok"):
            return {"status": 200, "body": result}

        reason = str(result.get("reason", "unknown"))
        if reason in {"invalid_actor_id", "invalid_resource_id", "invalid_action"}:
            status = 400
        elif reason in {"resource_not_found"}:
            status = 404
        else:
            status = 409
        return {"status": status, "body": result}

    def handle_batch(self, payloads: list[dict[str, Any]]) -> dict[str, Any]:
        outputs: list[dict[str, Any]] = []
        success = 0
        failed = 0
        for payload in payloads:
            output = self.handle(payload)
            outputs.append(output)
            if int(output.get("status", 500)) < 400:
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed, "outputs": outputs}

    def diagnostics(self) -> dict[str, Any]:
        return {
            "resource_count": self.service.count(),
            "resources": self.service.snapshot(),
            "audit_count": self.audit.count(),
            "audit_summary": self.audit.summary(),
        }

    def audit_events(self) -> list[dict[str, Any]]:
        return self.audit.list_all()

    def clear_audit(self) -> None:
        self.audit.clear()

    def last_audit_event(self) -> dict[str, Any] | None:
        events = self.audit_events()
        if not events:
            return None
        return events[-1]

    def count_by_status(self, status: str) -> int:
        target = status.strip().lower()
        return len([item for item in self.audit_events() if str(item.get("status", "")).lower() == target])

    def count_by_type(self, event_type: str) -> int:
        target = event_type.strip()
        return len([item for item in self.audit_events() if str(item.get("event_type", "")) == target])

    def audit_snapshot(self) -> dict[str, Any]:
        events = self.audit_events()
        return {
            "count": len(events),
            "summary": self.audit.summary(),
            "latest": events[-1] if events else None,
        }

    def reset(self) -> None:
        self.clear_audit()

