from __future__ import annotations

from threading import Lock
from typing import Any


class AuditStore:
    def __init__(self) -> None:
        self._lock = Lock()
        self._entries: list[dict[str, Any]] = []

    def append(self, entry: dict[str, Any]) -> None:
        with self._lock:
            self._entries.append(dict(entry))

    def append_event(
        self,
        *,
        event_type: str,
        actor_id: str,
        resource_id: str,
        status: str,
        reason: str,
        metadata: dict[str, Any] | None = None,
    ) -> None:
        item = {
            "event_type": event_type.strip() or "unknown",
            "actor_id": actor_id.strip(),
            "resource_id": resource_id.strip(),
            "status": status.strip().lower() or "unknown",
            "reason": reason.strip() or "none",
            "metadata": dict(metadata or {}),
        }
        self.append(item)

    def list_all(self) -> list[dict[str, Any]]:
        with self._lock:
            return [dict(item) for item in self._entries]

    def by_actor(self, actor_id: str) -> list[dict[str, Any]]:
        key = actor_id.strip()
        if not key:
            return []
        with self._lock:
            return [dict(item) for item in self._entries if str(item.get("actor_id", "")) == key]

    def by_resource(self, resource_id: str) -> list[dict[str, Any]]:
        key = resource_id.strip()
        if not key:
            return []
        with self._lock:
            return [dict(item) for item in self._entries if str(item.get("resource_id", "")) == key]

    def by_status(self, status: str) -> list[dict[str, Any]]:
        key = status.strip().lower()
        if not key:
            return []
        with self._lock:
            return [dict(item) for item in self._entries if str(item.get("status", "")) == key]

    def count(self) -> int:
        with self._lock:
            return len(self._entries)

    def clear(self) -> None:
        with self._lock:
            self._entries.clear()

    def summary(self) -> dict[str, int]:
        with self._lock:
            out: dict[str, int] = {}
            for item in self._entries:
                t = str(item.get("event_type", "unknown"))
                out[t] = out.get(t, 0) + 1
            return out

    def has_event(self, event_type: str, status: str) -> bool:
        target_type = event_type.strip()
        target_status = status.strip().lower()
        if not target_type or not target_status:
            return False
        with self._lock:
            return any(
                str(item.get("event_type", "")) == target_type
                and str(item.get("status", "")).lower() == target_status
                for item in self._entries
            )

