from __future__ import annotations

from typing import Any

from audit_store import AuditStore


VALID_ACTIONS = {"enable", "disable", "rotate_key"}


class OperationService:
    def __init__(self, audit_store: AuditStore) -> None:
        self._audit = audit_store
        self._resource_state: dict[str, dict[str, Any]] = {}

    def seed(self, resources: list[dict[str, Any]]) -> None:
        self._resource_state.clear()
        for item in resources:
            resource_id = str(item.get("resource_id", "")).strip()
            if not resource_id:
                raise ValueError("resource_id required")
            self._resource_state[resource_id] = {
                "resource_id": resource_id,
                "enabled": bool(item.get("enabled", True)),
                "key_version": int(item.get("key_version", 1)),
            }

    def perform(self, payload: dict[str, Any]) -> dict[str, Any]:
        actor_id = str(payload.get("actor_id", "")).strip()
        resource_id = str(payload.get("resource_id", "")).strip()
        action = str(payload.get("action", "")).strip().lower()

        if not actor_id:
            return {"ok": False, "reason": "invalid_actor_id"}
        if not resource_id:
            return {"ok": False, "reason": "invalid_resource_id"}
        if action not in VALID_ACTIONS:
            return {"ok": False, "reason": "invalid_action"}

        resource = self._resource_state.get(resource_id)
        if resource is None:
            return {"ok": False, "reason": "resource_not_found"}

        if action == "enable":
            if resource["enabled"]:
                self._audit.append_event(
                    event_type="resource_enable",
                    actor_id=actor_id,
                    resource_id=resource_id,
                    status="success",
                    reason="already_enabled",
                )
                return {"ok": True, "reason": "already_enabled", "resource": dict(resource)}
            resource["enabled"] = True
            self._audit.append_event(
                event_type="resource_enable",
                actor_id=actor_id,
                resource_id=resource_id,
                status="success",
                reason="enabled",
            )
            return {"ok": True, "reason": "enabled", "resource": dict(resource)}

        if action == "disable":
            if not resource["enabled"]:
                self._audit.append_event(
                    event_type="resource_disable",
                    actor_id=actor_id,
                    resource_id=resource_id,
                    status="success",
                    reason="already_disabled",
                )
                return {"ok": True, "reason": "already_disabled", "resource": dict(resource)}
            resource["enabled"] = False
            self._audit.append_event(
                event_type="resource_disable",
                actor_id=actor_id,
                resource_id=resource_id,
                status="success",
                reason="disabled",
            )
            return {"ok": True, "reason": "disabled", "resource": dict(resource)}

        # rotate_key
        if not resource["enabled"]:
            # Bug: denied rotate operation is not audit-logged.
            return {"ok": False, "reason": "resource_disabled"}

        resource["key_version"] = int(resource["key_version"]) + 1
        self._audit.append_event(
            event_type="resource_rotate_key",
            actor_id=actor_id,
            resource_id=resource_id,
            status="success",
            reason="rotated",
            metadata={"key_version": resource["key_version"]},
        )
        return {"ok": True, "reason": "rotated", "resource": dict(resource)}

    def snapshot(self) -> dict[str, dict[str, Any]]:
        return {key: dict(value) for key, value in self._resource_state.items()}

    def count(self) -> int:
        return len(self._resource_state)

